modo-arranque:
cat > /home/learner/aso/p11/modo-arranque.sh <<'ASO_EOF'
#!/bin/bash
(($#!=0)) && { echo "uso: modo-arranque.sh" >&2; exit 1; }
target=$(systemctl get-default)
case $target in
  graphical.target) echo "$target: modo gráfico";;
  multi-user.target) echo "$target: modo texto";;
  *) echo "$target: otro modo";;
esac
exit 0
ASO_EOF
chmod 755 /home/learner/aso/p11/modo-arranque.sh
chown learner:learner /home/learner/aso/p11/modo-arranque.sh
